    for (i, recipe) in recipes.iter().enumerate() {
      if i > 0 {
        print!(" ");
      }
      print!("{}", recipe.recipe_path());
    }
    println!();

    if recipes.is_empty() && config.verbosity.loud() {
      eprintln!("Justfile contains no recipes.");
    }
  }

  pub(crate) fn takes_arguments(&self) -> bool {
    match self {
      Self::Changelog
      | Self::Dump { .. }
      | Self::Edit
      | Self::Format
      | Self::Init
      | Self::Man
      | Self::Summary
      | Self::Variables => false,
      Self::Choose { .. }
      | Self::Command { .. }
      | Self::Completions { .. }
      | Self::Evaluate { .. }
      | Self::Groups
      | Self::List { .. }
      | Self::Request { .. }
      | Self::Run { .. }
      | Self::Show { .. }
      | Self::Usage { .. } => true,
